        breedCtx.fillStyle = '#fff';
        breedCtx.fillRect(0, 0, breedCanvas.width, breedCanvas.height);
        breedCtx.font = '24px Arial';
        breedCtx.textAlign = 'center';
        breedCtx.textBaseline = 'middle';
        breedCtx.fillStyle = '#333';
